import{_ as i,o as s,c as a,a2 as t}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Functional Permissions Engine","description":"","frontmatter":{},"headers":[],"relativePath":"permissions/functional-permissions.md","filePath":"permissions/functional-permissions.md"}'),n={name:"permissions/functional-permissions.md"};function o(r,e,d,l,c,h){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="functional-permissions-engine" tabindex="-1">Functional Permissions Engine <a class="header-anchor" href="#functional-permissions-engine" aria-label="Permalink to &quot;Functional Permissions Engine&quot;">​</a></h1><p>Answers &quot;which screens/actions can this user open&quot;, independent of which data rows they&#39;d see once inside (that&#39;s <a href="./data-scope">data-scope.md</a>). Built entirely on <code>spatie/laravel-permission</code> (already installed, unused before this engine) — Spatie remains the system of record at read time, so every <code>$user-&gt;can()</code>, <code>@can</code>, and policy check keeps working unmodified.</p><h2 id="why-generate-instead-of-hand-write" tabindex="-1">Why generate instead of hand-write <a class="header-anchor" href="#why-generate-instead-of-hand-write" aria-label="Permalink to &quot;Why generate instead of hand-write&quot;">​</a></h2><p>The Dynamic Table / Dynamic Record View / navigation-tree engines already call <code>auth()-&gt;user()-&gt;can($application-&gt;permission_name)</code> everywhere — that hook existed before this engine and was simply never fed real permission names. Building this engine was mostly about <strong>answering the question the UI was already asking</strong>, not adding a new layer.</p><p>Every <code>modules</code>/<code>sub_modules</code>/<code>applications</code> row already carries a hierarchical <code>code</code> (<code>fin-gl-jou</code>, generated by <code>RecordCodeBuilder</code> — see <code>.ai/rules/code-field-hierarchy.md</code>). Permission names are derived directly from that code, so there is never a second naming scheme to keep in sync by hand.</p><h2 id="php-artisan-permissions-sync" tabindex="-1"><code>php artisan permissions:sync</code> <a class="header-anchor" href="#php-artisan-permissions-sync" aria-label="Permalink to &quot;\`php artisan permissions:sync\`&quot;">​</a></h2><p>Run after seeding any new <code>Module</code>/<code>SubModule</code>/<code>Application</code> row.</p><ul><li><strong>Modules &amp; sub-modules</strong> get exactly two actions: <code>{code}.view</code>, <code>{code}.update</code>.</li><li><strong>Applications</strong> get six standard actions — <code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>export</code>, <code>print</code> — plus whatever <code>custom_actions</code> (a <code>json</code> column on <code>applications</code>) the Application declares, e.g. <code>post</code> for a journal-entry Application.</li><li>Stamps <code>permission_name = &quot;{code}.view&quot;</code> on every row (used by <code>RecordReferenceAccess::applicationAccessible()</code> and <code>NavigationTreeService</code> to gate the page and filter the sidebar at all three levels).</li><li>Idempotent — safe to re-run; only creates permissions that don&#39;t already exist, and calls <code>PermissionRegistrar::forgetCachedPermissions()</code> once at the end.</li></ul><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Declaring a custom action on an Application:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Application</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;custom_actions&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;post&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// permissions:sync then creates fin-gl-jou.post alongside the six standard ones.</span></span></code></pre></div><h2 id="grant-tables" tabindex="-1">Grant tables <a class="header-anchor" href="#grant-tables" aria-label="Permalink to &quot;Grant tables&quot;">​</a></h2><p>Four tables, all under <code>Modules/HR/Database/Migrations/</code>. A user&#39;s effective permission set is the <strong>union</strong> of every applicable row across all four:</p><table tabindex="0"><thead><tr><th>Table</th><th>Grants to</th><th>Notes</th></tr></thead><tbody><tr><td><code>department_permissions</code></td><td>Everyone in a department</td><td>Direct grants only — <strong>not</strong> inherited down the department tree (a child department doesn&#39;t silently gain the parent&#39;s module access; see <a href="./data-scope#departments-are-a-shared-catalog">data-scope.md</a>)</td></tr><tr><td><code>job_title_permissions</code></td><td>Everyone holding a job title, any grade</td><td>The baseline every grade of a title gets</td></tr><tr><td><code>job_title_grade_permissions</code></td><td>Holders of a job title <strong>at or above</strong> a grade</td><td>Comparison is always within the same <code>job_title_id</code>&#39;s own grade ladder — a senior in one title is never compared to a senior in another. E.g. &quot;General Accountant&quot; @ senior gets <code>fin-gl-jou.post</code>; junior does not</td></tr><tr><td><code>job_title_grade_roles</code></td><td>A named Spatie <strong>role</strong> (e.g. <code>finance_manager</code>) to holders of a job title, optionally grade-gated (<code>job_grade_id</code> nullable = every grade)</td><td>For roles the business names explicitly (&quot;Finance Manager&quot;), not just raw permissions</td></tr></tbody></table><h2 id="employeepermissionsynchronizer" tabindex="-1"><code>EmployeePermissionSynchronizer</code> <a class="header-anchor" href="#employeepermissionsynchronizer" aria-label="Permalink to &quot;\`EmployeePermissionSynchronizer\`&quot;">​</a></h2><p>The <strong>only</strong> writer to <code>model_has_permissions</code> / <code>model_has_roles</code>. Runs automatically on every <code>Employee::saved()</code> — hire, reassignment, promotion, termination all trigger a resync unconditionally (not just on the fields that changed, since the grant tables themselves can change independently of the employee row).</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">EmployeePermissionSynchronizer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($employee);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// or, to inspect without writing:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$target </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">EmployeePermissionSynchronizer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($employee); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// [&#39;permissions&#39; =&gt; [...], &#39;roles&#39; =&gt; [...]]</span></span></code></pre></div><p>A terminated/suspended employee (<code>status !== &#39;active&#39;</code>) is synced to <strong>zero</strong> permissions and roles immediately — not left until their next login.</p><p>Also invalidates the navigation-tree cache on every sync (<code>NavigationTreeService::invalidateCache()</code>) — that cache&#39;s key hashes Spatie <strong>role</strong> names only, so a permission-only grant (no role attached) would otherwise leave the sidebar serving a stale tree until an unrelated <code>Module</code>/<code>SubModule</code>/<code>Application</code> write happened to bump the version first. This was a real bug caught by <a href="./testing#cache-invalidation">a dedicated test</a>, not a theoretical one.</p><h2 id="drift-reconciliation" tabindex="-1">Drift reconciliation <a class="header-anchor" href="#drift-reconciliation" aria-label="Permalink to &quot;Drift reconciliation&quot;">​</a></h2><p>Because the synchronizer is the <em>only</em> writer, drift can only mean a sync call was missed — a direct DB edit to a grant table, a queued job that failed partway. <code>hr:permissions:reconcile</code> is the backstop:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hr:permissions:reconcile</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # recompute, fix, and report drift</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hr:permissions:reconcile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # report only, write nothing</span></span></code></pre></div><p>Iterates every active, logged-in <code>Employee</code> (<code>chunkById(200, ...)</code>), compares current Spatie state to what <code>EmployeePermissionSynchronizer::resolve()</code> computes fresh, and reports (then optionally corrects) any mismatch. Intended to run on a schedule, not just ad hoc.</p><h2 id="worked-example-general-accountant" tabindex="-1">Worked example: &quot;General Accountant&quot; <a class="header-anchor" href="#worked-example-general-accountant" aria-label="Permalink to &quot;Worked example: &quot;General Accountant&quot;&quot;">​</a></h2><p>The example that shaped this design, now backed by a passing test suite:</p><ol><li><code>department_permissions</code>: Finance department → <code>fin-gl-jou.view</code> (everyone in Finance can view the ledger, regardless of title).</li><li><code>job_title_permissions</code>: &quot;General Accountant&quot; → <code>fin-gl-jou.view</code> (redundant with #1 here, included for illustration — a title-level grant works even outside Finance).</li><li><code>job_title_grade_permissions</code>: &quot;General Accountant&quot; @ Senior grade → <code>fin-gl-jou.post</code>. A junior holding the same title has <code>view</code> but not <code>post</code>; promoting them to Senior (a plain <code>Employee</code> field update) flips <code>post</code> on with no other change.</li><li><code>job_title_grade_roles</code>: &quot;Finance Manager&quot; job title, no grade restriction → role <code>finance_manager</code> attached to every grade.</li></ol><h2 id="what-this-engine-deliberately-does-not-do" tabindex="-1">What this engine deliberately does not do <a class="header-anchor" href="#what-this-engine-deliberately-does-not-do" aria-label="Permalink to &quot;What this engine deliberately does not do&quot;">​</a></h2><ul><li><strong>No field-level permission table.</strong> A field&#39;s visibility is a <code>Column::visible()</code> / <code>ViewField</code> callback gated by a normal <code>can()</code> check against a normal permission — no new mechanism was needed once the standard-actions-plus-custom-actions shape existed.</li><li><strong>No per-request permission overrides / temporary grants.</strong> A grant always comes from the department/job-title/grade chain; there is no &quot;grant this one user this one permission for today&quot; table. Add one only when a real requirement demands it.</li></ul>`,26)])])}const m=i(n,[["render",o]]);export{g as __pageData,m as default};
